-- Glossary content (English). Definitions use [[slug|visible text]] for links to other terms
-- ([[slug]] alone shows the slug). Text is dollar-quoted ($$...$$), so apostrophes need no escaping.
-- Educational wording only: explain concepts, never recommend a product (MiFID II).
-- After editing this file locally run `make db-reset`.

INSERT INTO glossary_category (id, slug, name, position) VALUES
    (1, 'basics',        'Basics',        1),
    (2, 'investing',     'Investing',     2),
    (3, 'saving',        'Saving',        3),
    (4, 'credit-debt',   'Credit & debt', 4),
    (5, 'risk',          'Risk',          5);

INSERT INTO glossary_term
    (id, slug, name, full_name, category_id, position, short_description,
     definition_standard, definition_plain, example, aliases, graphic_key) VALUES

-- Basics ------------------------------------------------------------------------------------------

(1, 'inflation', 'Inflation', NULL, 1, 1,
 $$Prices rising over time, so each euro buys less$$,
 $$Inflation is the general rise in prices over time, which reduces the purchasing power of money. If inflation is 3% a year, something that costs € 100 today costs about € 103 next year. Money that earns less than inflation, for example cash in an account paying a lower [[interest-rate|interest rate]], loses value in real terms (see [[real-return|real return]]).$$,
 $$Inflation means things get more expensive over time. The same € 100 buys a little less each year. If your savings grow more slowly than prices, you can buy less with them later than you can today.$$,
 $$A coffee costs € 3.00 today. With 3% inflation it costs about € 3.09 next year and about € 4.03 in ten years.$$,
 ARRAY['rising prices','cost of living'], 'inflation-power'),

(2, 'interest-rate', 'Interest rate', NULL, 1, 2,
 $$The price of borrowing, or the reward for saving$$,
 $$An interest rate is the percentage a lender charges for lending money, or a bank pays you for holding your savings, usually quoted per year. It is the basis for [[compound-interest|compound interest]] and for the cost of credit (see [[apr|APR]]). Rates change with the economy and with [[inflation]].$$,
 $$An interest rate is the price of money. When you borrow, you pay it to the bank. When you save, the bank pays it to you. It is usually shown as a percentage per year.$$,
 $$A savings account pays 2.25% a year. On € 12,000 that is about € 270 in interest over twelve months.$$,
 ARRAY['rate','interest'], NULL),

(3, 'compound-interest', 'Compound interest', 'Interest on interest', 1, 3,
 $$Interest that earns interest on itself$$,
 $$Compound interest is interest calculated on both the original amount and the interest already added to it. Each period the base grows, so the interest you earn grows too. The longer the horizon and the higher the [[interest-rate|interest rate]], the stronger the effect.$$,
 $$With compound interest, the interest you earned also starts earning interest. Your money grows a little faster every year, like a snowball rolling downhill. Time matters most.$$,
 $$€ 1,000 at 5% a year becomes about € 1,630 after 10 years and € 4,320 after 30, with no extra deposits.$$,
 ARRAY['interest on interest','compounding'], 'compound-growth'),

(4, 'budget', 'Budget', NULL, 1, 4,
 $$A plan for what comes in and what goes out$$,
 $$A budget is a plan that compares your expected income, usually your [[net-income|net income]], with your expected spending over a period, usually a month. It separates [[fixed-costs|fixed costs]] from everyday spending and shows how much is left over for your [[savings-rate|savings rate]] or an [[emergency-fund|emergency fund]].$$,
 $$A budget is a simple plan for your money. You write down what comes in and what goes out each month. Then you can see what is left to save, before it quietly disappears.$$,
 $$Income € 2,150, fixed costs € 1,100, everyday spending € 700. That leaves € 350 for saving.$$,
 ARRAY['spending plan'], NULL),

(17, 'net-income', 'Net income', 'Take-home pay', 1, 5,
 $$What actually reaches your account after deductions$$,
 $$Net income is the amount you receive after income tax and social contributions, such as pension, health and unemployment insurance, are deducted from your gross salary. It is the figure a [[budget]] is usually built on, because it is the money you can actually spend or save.$$,
 $$Net income is the money that really lands in your account each month. Your contract shows a bigger number, but taxes and insurance are taken out first. Plan with the smaller number.$$,
 $$A gross salary of € 3,200 a month can leave a net income of roughly € 2,150, depending on tax class, insurance and country.$$,
 ARRAY['take-home pay','net salary','net pay'], NULL),

(18, 'fixed-costs', 'Fixed costs', NULL, 1, 6,
 $$Bills that come every month at roughly the same amount$$,
 $$Fixed costs are regular expenses that stay about the same from month to month and are hard to change quickly, such as rent, insurance, subscriptions and loan instalments. Variable costs, such as groceries or going out, change with your choices. Knowing your fixed costs shows how much of your [[net-income|net income]] is already committed and is the starting point for sizing an [[emergency-fund|emergency fund]].$$,
 $$Fixed costs are the bills you pay every month no matter what: rent, insurance, your phone contract. They are already spoken for before you buy anything else.$$,
 $$Rent € 800, insurance € 60, phone € 25 and a transport pass € 60 add up to € 945 of fixed costs a month.$$,
 ARRAY['fixed expenses','recurring costs','bills'], NULL),

(19, 'liquidity', 'Liquidity', NULL, 1, 7,
 $$How quickly you can turn something into cash$$,
 $$Liquidity describes how quickly and cheaply an asset can be converted into cash without losing value. Money in a current or instant-access savings account is highly liquid. A [[fixed-term-deposit|fixed-term deposit]] is less liquid until it matures, and property is illiquid because selling it takes time and costs money. An [[emergency-fund|emergency fund]] needs high liquidity.$$,
 $$Liquidity means how fast you can get your money out when you need it. Cash in your account: right now. Money locked for a year: later. A flat: months, and with costs.$$,
 $$You need € 800 for a car repair tomorrow. Money in your savings account is available at once; money in a 12-month deposit is not.$$,
 ARRAY['access to money','easy access'], NULL),

(20, 'opportunity-cost', 'Opportunity cost', NULL, 1, 8,
 $$What you give up when you choose one option over another$$,
 $$Opportunity cost is the value of the best alternative you give up when you make a choice. Money spent today cannot also be saved or invested, so its opportunity cost includes the growth it could have had through [[compound-interest|compound interest]]. Thinking in opportunity costs makes trade-offs visible; it does not mean that spending is wrong.$$,
 $$Every euro can only be used once. If you spend it on one thing, you cannot use it for something else. That missed alternative is the opportunity cost.$$,
 $$A € 3 coffee every working day costs about € 660 a year. The opportunity cost is whatever else those € 660 could have done, for example sit in savings.$$,
 ARRAY['trade-off'], NULL),

-- Investing ---------------------------------------------------------------------------------------

(5, 'stock', 'Stock', NULL, 2, 1,
 $$A small ownership share in a company$$,
 $$A stock (also called a share) is a small piece of ownership in a company. Its price moves with the company's results and with market expectations, so it can rise or fall. Owners can earn a [[capital-gain|capital gain]] if the price rises, and some companies pay part of their profit to owners as a [[dividend]]. The prices of many stocks tracked together form an [[index]].$$,
 $$A stock is a tiny piece of a company. If the company does well, your piece can be worth more. If it does badly, it can be worth less. Some companies also share part of their profit with owners, called a [[dividend]].$$,
 $$If a company is split into 1,000,000 shares and you hold 100 of them, you own 0.01% of the company.$$,
 ARRAY['share','equity'], NULL),

(6, 'etf', 'ETF', 'Exchange-traded fund', 2, 2,
 $$A basket of many investments bought as one$$,
 $$An ETF (exchange-traded fund) is a fund that holds many [[stock|stocks]] or [[bond|bonds]] and is traded on an exchange like a single share. Because it spreads money across many holdings, it provides built-in [[diversification]]. Most ETFs track an [[index]], some pay out a [[dividend]], and all charge running costs shown as the [[ter|TER]].$$,
 $$An ETF is a basket of many [[stock|stocks]] and [[bond|bonds]] that you buy as one share. Your money is spread across lots of companies, so one bad apple hurts less. That is [[diversification]]. Many ETFs simply copy an [[index]].$$,
 $$Put € 100 into a world-stock ETF and you own a tiny slice of thousands of companies at once. If one of them struggles, the others cushion the fall.$$,
 ARRAY['exchange traded fund','index fund','fund'], 'diversification'),

(7, 'dividend', 'Dividend', NULL, 2, 3,
 $$A slice of profit paid out to shareholders$$,
 $$A dividend is a part of a company's profit that it pays out to its shareholders, usually once or twice a year. Companies are not obliged to pay one, and the amount can change or stop. Together with price changes, it is one of the ways a [[stock]] can provide a [[return]].$$,
 $$A dividend is money a company pays to the people who own its shares, out of its profit. Not every company pays one, and the amount can go up, go down or stop.$$,
 $$A company pays € 2 per share per year. If you hold 50 shares, you receive € 100 before any taxes.$$,
 ARRAY['payout','distribution'], NULL),

(8, 'diversification', 'Diversification', NULL, 2, 4,
 $$Spreading money so one bad result hurts less$$,
 $$Diversification means spreading money across many different investments, such as different companies, sectors, countries or asset types like [[stock|stocks]] and [[bond|bonds]]. If one holding falls, others may hold up or rise, which reduces the effect on the total. It lowers the impact of any single holding, but it does not remove market [[volatility]].$$,
 $$Do not put all your eggs in one basket. Diversification means spreading your money over many different things, so one bad result hurts less. An [[etf|ETF]] does this in one step.$$,
 $$Two portfolios of € 1,000: one holds a single company's shares, the other holds 500 companies. If one company loses half its value, the first portfolio loses € 500 and the second about € 1.$$,
 ARRAY['spreading risk'], 'diversification'),

(9, 'bond', 'Bond', NULL, 2, 5,
 $$A loan you give to a government or a company$$,
 $$A bond is a loan that you give to a government or a company. The issuer promises to pay regular interest, called the coupon, and to return the original amount on a set date, called maturity. Bond prices can still change before that date, mainly when market [[interest-rate|interest rates]] move, and the issuer may fail to pay (see [[default-risk|default risk]]).$$,
 $$A bond is like lending money to a government or a company. They pay you interest and give the money back on an agreed date. The risk is that they cannot pay you back in full.$$,
 $$A bond of € 1,000 pays 3% interest a year for 5 years: € 30 each year, then your € 1,000 back at the end.$$,
 ARRAY['debt security','government bond','coupon'], NULL),

(10, 'index', 'Index', NULL, 2, 6,
 $$A number that tracks a group of investments$$,
 $$An index measures how a chosen group of investments performs, for example the largest companies in a country. It is a statistic, not something you buy directly, but many [[etf|ETFs]] are built to follow one. Examples include the DAX, which tracks 40 large German companies, and the S&P 500, which tracks 500 large US companies.$$,
 $$An index is a score that shows how a group of companies is doing, a bit like a league table for the stock market. You cannot buy the index itself, but some funds copy it.$$,
 $$If an index of 40 companies moves from 10,000 to 10,500 points, the group has risen roughly 5%.$$,
 ARRAY['stock index','benchmark'], NULL),

(21, 'portfolio', 'Portfolio', NULL, 2, 7,
 $$Everything you have invested, seen as one whole$$,
 $$A portfolio is the full set of investments a person holds, such as [[stock|stocks]], [[etf|ETFs]], [[bond|bonds]] and cash. Looking at the portfolio as a whole, rather than at single holdings, shows its overall [[asset-allocation|asset allocation]], its level of [[diversification]] and how it matches your [[time-horizon|time horizon]].$$,
 $$Your portfolio is everything you have invested, all together. Instead of asking "how is this one share doing?", you look at the whole picture.$$,
 $$€ 3,000 in a world-stock ETF, € 1,500 in bonds and € 500 in one company's shares make a € 5,000 portfolio, split 60% / 30% / 10%.$$,
 ARRAY['holdings','investments'], NULL),

(22, 'return', 'Return', NULL, 2, 8,
 $$How much an investment gained or lost$$,
 $$Return is the gain or loss on an investment over a period, usually shown as a percentage of the amount invested. Total return includes both price changes ([[capital-gain|capital gains]] or losses) and income such as a [[dividend]] or interest. Past returns do not guarantee future returns, and a return says nothing about the risk taken to get it.$$,
 $$Return is what your investment earned, or lost, compared with what you put in. If you put in € 100 and now have € 108, your return is 8%.$$,
 $$You invest € 1,000. A year later it is worth € 1,080 and you received € 20 in dividends. Your total return is € 100, or 10%.$$,
 ARRAY['yield','performance','gain'], NULL),

(23, 'real-return', 'Real return', 'Inflation-adjusted return', 2, 9,
 $$What you earn after inflation is taken into account$$,
 $$Real return is the [[return]] on an investment or savings after subtracting [[inflation]]. It shows how much your purchasing power actually changed. As a quick estimate, real return is the nominal return minus the inflation rate. A positive nominal return can still be a negative real return.$$,
 $$Real return tells you whether you can really buy more with your money. If your savings grow 2% but prices rise 3%, you can actually buy less than before.$$,
 $$Savings earn 2% while inflation is 3%: the real return is about −1%. An investment that earns 5% in the same year has a real return of about 2%.$$,
 ARRAY['inflation-adjusted return'], NULL),

(24, 'capital-gain', 'Capital gain', NULL, 2, 10,
 $$Profit from selling something for more than you paid$$,
 $$A capital gain is the increase in value of an investment, such as a [[stock]], above the price you paid for it. While you still hold it, the gain is unrealised and can disappear again; once you sell, it is realised. A fall below the purchase price is a capital loss. Taxes and fees reduce the gain; the rules depend on the country.$$,
 $$A capital gain is the profit you make when something you bought becomes worth more than you paid. It only becomes real money when you sell. Until then, the price can still fall.$$,
 $$You buy 100 shares at € 40 and sell them at € 52. Your capital gain is € 1,200, before taxes and fees.$$,
 ARRAY['price gain','profit','capital loss'], NULL),

(25, 'asset-allocation', 'Asset allocation', NULL, 2, 11,
 $$How your money is split between types of investment$$,
 $$Asset allocation is how a [[portfolio]] is divided between asset types, such as [[stock|stocks]], [[bond|bonds]] and cash. Each type behaves differently: stocks tend to have higher [[volatility]] and higher long-term growth potential, bonds and cash tend to move less. The split largely determines how much a portfolio swings, so it is usually related to the investor's [[time-horizon|time horizon]] and [[risk-tolerance|risk tolerance]].$$,
 $$Asset allocation is your money's mix. How much is in shares, how much in bonds, how much in cash? The mix decides how bumpy the ride will be, more than any single choice inside it.$$,
 $$Portfolio A holds 80% stocks and 20% bonds; portfolio B holds 40% stocks and 60% bonds. In a year when stocks fall 20% and bonds stay flat, A loses about 16% and B about 8%.$$,
 ARRAY['investment mix','asset mix'], NULL),

(26, 'cost-averaging', 'Cost averaging', 'Regular investing of a fixed amount', 2, 12,
 $$Investing the same amount at regular intervals$$,
 $$Cost averaging means investing a fixed amount at regular intervals, for example every month through a savings plan, regardless of the current price. When prices are low, the same amount buys more units; when prices are high, it buys fewer. This smooths the average purchase price over time and removes the need to pick a "right moment". It does not guarantee a profit or protect against losses.$$,
 $$Cost averaging means putting in the same amount every month, whatever the price. When prices are low you get more for your money, when they are high you get less. You never have to guess the best day to buy.$$,
 $$€ 100 a month for three months at prices of € 50, € 40 and € 50 buys 2 + 2.5 + 2 = 6.5 units. You paid € 300, an average of about € 46.15 per unit.$$,
 ARRAY['savings plan','dollar-cost averaging','euro-cost averaging','sparplan'], NULL),

(27, 'ter', 'TER', 'Total expense ratio', 2, 13,
 $$The yearly running cost of a fund, as a percentage$$,
 $$The TER (total expense ratio) shows the yearly running costs of a fund, such as an [[etf|ETF]], as a percentage of the money invested. It covers management and administration and is taken from the fund's assets, so you do not pay it as a separate bill; it reduces your [[return]]. It does not include the costs of buying or selling the fund itself.$$,
 $$The TER is the yearly fee a fund charges for running it. You never see a bill: it is quietly taken out of the fund. Small differences add up over many years.$$,
 $$On € 10,000 invested, a TER of 0.2% costs about € 20 a year, and a TER of 1.5% about € 150 a year.$$,
 ARRAY['total expense ratio','ongoing charges','fund fees'], NULL),

-- Saving ------------------------------------------------------------------------------------------

(11, 'emergency-fund', 'Emergency fund', NULL, 3, 1,
 $$Cash set aside for the unexpected$$,
 $$An emergency fund is money kept in easily accessible savings to cover unexpected costs or a loss of income, such as a repair or a gap between jobs. A common guideline is to hold several months of essential expenses, adjusted to personal circumstances. It is kept separate from long-term investments so that it is available when needed, which is why it needs high [[liquidity]]. See also [[budget]].$$,
 $$An emergency fund is money you keep aside for surprises: a broken phone, a car repair, or a few weeks without income. It sits somewhere safe and easy to reach, not tied up in investments.$$,
 $$Essential costs are € 1,500 a month. A three-month cushion would be € 4,500.$$,
 ARRAY['rainy day fund','safety net','buffer'], NULL),

(12, 'savings-rate', 'Savings rate', NULL, 3, 2,
 $$The share of income you put aside$$,
 $$The savings rate is the percentage of your income that you set aside instead of spending, calculated as savings divided by [[net-income|net income]] over the same period. A higher rate leaves more for goals such as an [[emergency-fund|emergency fund]]. Do not confuse it with the [[interest-rate|interest rate]] paid on a savings account.$$,
 $$Your savings rate is how much of the money you earn you keep instead of spending. If you save € 10 of every € 100, your savings rate is 10%.$$,
 $$Income of € 2,150 a month and € 215 saved gives a savings rate of 10%.$$,
 ARRAY['saving rate'], NULL),

(28, 'standing-order', 'Standing order', NULL, 3, 3,
 $$An automatic transfer that repeats on a set date$$,
 $$A standing order is an instruction to your bank to transfer a fixed amount to the same account on a regular schedule, for example on the first of every month. You set it up once and can change or cancel it at any time. Used for saving, it moves money aside right after payday, before it can be spent, which helps keep a steady [[savings-rate|savings rate]].$$,
 $$A standing order is a transfer your bank repeats for you automatically, every month. Set it up once for the day after payday, and your saving happens without you having to remember.$$,
 $$A standing order of € 100 on the 1st of each month to a savings account sets aside € 1,200 a year.$$,
 ARRAY['recurring transfer','automatic transfer','dauerauftrag'], NULL),

(29, 'fixed-term-deposit', 'Fixed-term deposit', NULL, 3, 4,
 $$Savings locked for a set period at a set rate$$,
 $$A fixed-term deposit is a savings product where you leave a sum with a bank for an agreed period, such as 6 or 12 months, at an [[interest-rate|interest rate]] fixed in advance. In exchange for the fixed rate, the money usually cannot be withdrawn early, or only with a penalty, so it has lower [[liquidity]] than an instant-access account. Like other deposits, it falls under the [[deposit-guarantee|deposit guarantee]].$$,
 $$A fixed-term deposit is savings you promise not to touch for a while, for example a year. In return, the bank promises you a fixed interest rate for that time. You know exactly what you will get.$$,
 $$€ 5,000 in a 12-month fixed-term deposit at 2.5% pays € 125 in interest at the end of the year.$$,
 ARRAY['term deposit','time deposit','festgeld'], NULL),

(30, 'deposit-guarantee', 'Deposit guarantee', 'Deposit guarantee scheme', 3, 5,
 $$Protection of your savings if a bank fails$$,
 $$A deposit guarantee scheme protects money held in bank accounts if the bank fails. In the EU, deposits are protected up to € 100,000 per person per bank, including current accounts, savings accounts and [[fixed-term-deposit|fixed-term deposits]]. Investments such as [[stock|stocks]] or [[etf|ETFs]] are not deposits; they are held separately for the customer and are not covered by this scheme.$$,
 $$If a bank goes bust, your savings there are protected up to € 100,000. This is an EU-wide rule. It covers money in accounts, not shares or funds, which belong to you anyway and are kept separately.$$,
 $$You hold € 60,000 in a savings account and € 20,000 in a current account at one bank: the full € 80,000 is protected.$$,
 ARRAY['deposit insurance','deposit protection','einlagensicherung'], NULL),

-- Credit & debt -----------------------------------------------------------------------------------

(13, 'apr', 'APR', 'Annual percentage rate', 4, 1,
 $$The yearly cost of a loan, fees included$$,
 $$APR (annual percentage rate) expresses the total yearly cost of borrowing as a percentage, including the [[interest-rate|interest rate]] and certain mandatory fees. It lets you compare loans, such as an [[instalment-loan|instalment loan]], on equal terms. Two loans with the same interest rate can have different APRs if their fees differ.$$,
 $$APR shows the full yearly price of a loan: not only the interest, but also the fees you must pay. It lets you compare loans fairly. A lower APR means a cheaper loan.$$,
 $$Loan A: 6.0% interest, no fees, APR 6.0%. Loan B: 5.8% interest plus fees, APR 6.4%. Loan B has the lower rate but costs more per year.$$,
 ARRAY['annual percentage rate','effective interest rate'], NULL),

(14, 'credit-score', 'Credit score', NULL, 4, 2,
 $$A number summarising how reliably you repay$$,
 $$A credit score is a number that credit agencies calculate from your borrowing and repayment history. Lenders use it to judge how likely you are to repay, which can affect whether you are approved and the [[interest-rate|interest rate]] you are offered. Paying on time and keeping debt, including an [[overdraft]], moderate generally supports a higher score.$$,
 $$A credit score is like a report card for how you handle debt. Paying bills on time helps it. Missed payments hurt it. A better score can make borrowing cheaper.$$,
 $$Missing several payments on a credit card can lower your score and make a later loan more expensive.$$,
 ARRAY['credit rating','schufa'], NULL),

(31, 'overdraft', 'Overdraft', NULL, 4, 3,
 $$Spending more than is in your current account$$,
 $$An overdraft lets you spend more than the balance of your current account, up to an agreed limit. It is a form of credit: the bank charges interest on the negative balance, and overdraft rates are usually much higher than those of an [[instalment-loan|instalment loan]]. It is designed for short gaps, not for long-term borrowing.$$,
 $$An overdraft means your account goes below zero and the bank lends you the difference. It is handy for a few days, but it is one of the most expensive ways to borrow.$$,
 $$Being € 500 overdrawn for 30 days at 12% a year costs about € 5 in interest. The same € 500 overdrawn for a whole year costs about € 60.$$,
 ARRAY['arranged overdraft','dispo','negative balance'], NULL),

(32, 'instalment-loan', 'Instalment loan', NULL, 4, 4,
 $$A loan repaid in equal monthly payments$$,
 $$An instalment loan is a loan of a fixed amount that is repaid in regular, usually equal, monthly payments over an agreed term. Each payment covers interest plus part of the [[principal]]. The total cost depends on the amount, the term and the [[apr|APR]]: a longer term lowers the monthly payment but increases the total interest paid.$$,
 $$An instalment loan is money you borrow once and pay back in the same amount every month until it is gone. Longer loans have smaller monthly payments, but cost more in total.$$,
 $$€ 10,000 borrowed for 4 years at 7% a year means about € 239 a month. In total you pay back about € 11,490.$$,
 ARRAY['personal loan','consumer loan','installment loan'], NULL),

(33, 'principal', 'Principal', NULL, 4, 5,
 $$The amount you borrowed, without the interest$$,
 $$The principal is the original amount borrowed in a loan, or invested, not counting interest. In an [[instalment-loan|instalment loan]], each payment is split between interest and principal: at the start most of it is interest, and over time a growing share reduces the principal. Interest is always calculated on the principal still owed.$$,
 $$The principal is the money you actually borrowed. Interest comes on top. Every payment you make shrinks the principal a little, so you pay less interest over time.$$,
 $$On a € 10,000 loan at 7% with € 239 monthly payments, the first payment is about € 58 interest and € 181 principal.$$,
 ARRAY['loan amount','capital'], NULL),

(34, 'mortgage', 'Mortgage', NULL, 4, 6,
 $$A long-term loan to buy property, secured on that property$$,
 $$A mortgage is a long-term loan used to buy property, with the property itself as security: if the borrower cannot repay, the lender can sell it. Mortgages often run for 20 to 30 years, with the [[interest-rate|interest rate]] fixed for part of that time. Because the term is long, small differences in the rate change the total cost by a large amount.$$,
 $$A mortgage is a big loan to buy a home, paid back over many years. The home is the bank's guarantee: if you stop paying, the bank can sell it.$$,
 $$€ 200,000 borrowed over 25 years at 4% means about € 1,056 a month, and about € 117,000 in interest over the whole term.$$,
 ARRAY['home loan','housing loan','baufinanzierung'], NULL),

-- Risk --------------------------------------------------------------------------------------------

(15, 'volatility', 'Volatility', NULL, 5, 1,
 $$How strongly a price moves up and down$$,
 $$Volatility measures how much and how quickly the price of an investment moves up and down. High volatility means large swings in both directions, low volatility means smaller ones. It describes uncertainty, not direction. [[stock|Stocks]] are usually more volatile than [[bond|bonds]], and volatility tends to rise sharply in a [[bear-market|bear market]].$$,
 $$Volatility is how bumpy the ride is. A very volatile investment can jump up or drop down a lot in a short time. A calm one moves slowly.$$,
 $$A price that moves between € 95 and € 105 in a month is less volatile than one that moves between € 70 and € 130.$$,
 ARRAY['price swings','fluctuation'], NULL),

(16, 'risk-tolerance', 'Risk tolerance', NULL, 5, 2,
 $$How much ups and downs you can accept$$,
 $$Risk tolerance describes how large a temporary loss you could accept, financially and emotionally, without abandoning your plan. It depends on your goals, your [[time-horizon|time horizon]] and your finances, and it differs from person to person. Understanding it helps you make sense of [[volatility]] and [[diversification]].$$,
 $$Risk tolerance is how much up and down you can handle without panicking. If a drop in value would make you sell in fear, your tolerance is lower. There is no right or wrong answer.$$,
 $$Two people see their investment fall 20% in a month. One shrugs and waits, the other sleeps badly. Their risk tolerance differs.$$,
 ARRAY['risk appetite','risk profile'], NULL),

(35, 'time-horizon', 'Time horizon', NULL, 5, 3,
 $$How long until you need the money$$,
 $$The time horizon is the period between investing money and needing it back. A longer horizon leaves more time to recover from falls in value and lets [[compound-interest|compound interest]] work longer, which is why it shapes the [[asset-allocation|asset allocation]] that fits a goal. A short horizon leaves little time to recover, so [[volatility]] matters more. A longer horizon does not remove risk.$$,
 $$Your time horizon is how long you can leave the money alone. Money for a holiday next summer has a short horizon. Money for retirement in 30 years has a long one, and more time to ride out the bumps.$$,
 $$Saving for a car in 2 years and saving for retirement in 30 years are different goals: a 20% fall one year before the car purchase hurts much more than one 29 years before retirement.$$,
 ARRAY['investment horizon','holding period'], NULL),

(36, 'default-risk', 'Default risk', NULL, 5, 4,
 $$The chance that a borrower cannot pay back$$,
 $$Default risk is the risk that a borrower, such as the issuer of a [[bond]], fails to pay interest or repay the [[principal]] on time. Rating agencies grade issuers by this risk. Borrowers with higher default risk usually have to offer a higher [[interest-rate|interest rate]] to attract lenders, so a higher rate is often compensation for higher risk, not a free extra.$$,
 $$Default risk is the chance that someone you lent money to cannot pay you back. The riskier the borrower, the more interest they have to offer. A very high rate is often a warning sign.$$,
 $$A government bond paying 3% and a bond from a struggling company paying 9%: the extra 6% reflects the higher chance that the company cannot pay.$$,
 ARRAY['credit risk','default'], NULL),

(37, 'bear-market', 'Bear market', NULL, 5, 5,
 $$A long fall in prices of 20% or more$$,
 $$A bear market is a period in which prices on a market, usually measured by an [[index]], fall by 20% or more from a recent peak, often accompanied by pessimism and high [[volatility]]. The opposite, a long period of rising prices, is called a bull market. Bear markets have occurred regularly in the past; how long they last and how quickly prices recover has varied widely.$$,
 $$A bear market is when prices fall a lot, by a fifth or more, and stay low for a while. It feels scary, and many people sell in panic. Markets have always gone through such periods.$$,
 $$An index falls from 16,000 to 12,000 points over several months. That is a 25% drop, so it counts as a bear market.$$,
 ARRAY['market downturn','market crash','bull market'], NULL),

(38, 'investment-scam', 'Investment scam', NULL, 5, 6,
 $$Fraud that promises high returns with little risk$$,
 $$An investment scam is a fraud in which someone persuades you to hand over money for an investment that is fake or misrepresented. Common warning signs are guaranteed high [[return|returns]] with no risk, pressure to decide quickly, contact through social media or messengers, requests to install remote-access software, and providers without a licence. Licensed firms can be checked in the financial regulator's register, such as that of BaFin in Germany.$$,
 $$An investment scam promises you lots of money, fast and without risk. That combination does not exist. If someone pushes you to decide now or asks for access to your phone or computer, stop and check first.$$,
 $$A message promises 30% a month on a "secret" crypto platform and asks you to install an app so a "broker" can help. Two classic warning signs at once: guaranteed returns and remote access.$$,
 ARRAY['fraud','investment fraud','ponzi scheme'], NULL);

